import { HttpStatus } from "@nestjs/common";
import { z } from "zod";
import { partnerException, validationException } from "../common/errors";

/**
 * lot-based-stock SA rev 1 / ADR-0055 D2/D3 (BE-LOT-002): the opaque lot group key and the lot picker cursor.
 * A key is generated by PostgreSQL (`memo_stock.lot_key`, inventory `stock.lot_key`):
 * - `ML` / `OL` + 32 hex (md5 of every item detail) for a mergeable group (Memo Stock / our stock);
 * - `MS` / `OS` + the row uuid for a group of one (empty lot, or a certificate number).
 * The server never trusts a client-sent snapshot: a key is validated by format and prefix before any query, and the
 * group is re-derived from the database on Save and Approve.
 */
export const LOT_KEY_RE = /^(ML|OL)[0-9a-f]{32}$|^(MS|OS)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
export const lotKeySchema = z.string().regex(LOT_KEY_RE);
export type LotKey = string;

/** Bounds of one apply (D6): candidates per group and locked rows per transaction. */
export const LOT_GROUP_MAX = 500;
export const LOT_TX_MAX = 2_000;

export const isLotKey = (value: unknown): value is LotKey => typeof value === "string" && LOT_KEY_RE.test(value);
/** Memo Stock (`M…`) or our stock (`O…`). */
export const lotSource = (key: LotKey): "STOCK" | "OWN_STOCK" => (key.startsWith("M") ? "STOCK" : "OWN_STOCK");
export const isMemoLot = (key: string | null | undefined): key is LotKey => typeof key === "string" && key.startsWith("M") && LOT_KEY_RE.test(key);
export const isOwnLot = (key: string | null | undefined): key is LotKey => typeof key === "string" && key.startsWith("O") && LOT_KEY_RE.test(key);
/** A mergeable group (ML / OL): may hold several stock rows. */
export const isMergedLot = (key: LotKey) => key[1] === "L";

/** 422 `STOCK_LOT_TOO_LARGE` (error-handling): a group above 500 candidates, or an apply above 2,000; nothing changed. */
export const stockLotTooLarge = (lotKey: string | null, limit: number) =>
  partnerException("STOCK_LOT_TOO_LARGE", HttpStatus.UNPROCESSABLE_ENTITY, null, { ...(lotKey ? { lotKey } : {}), limit });
/** 422 `STOCK_LOT_UNAVAILABLE`: the group has no open row at Save (taken or returned). */
export const stockLotUnavailable = (indexes: readonly number[]) =>
  partnerException("STOCK_LOT_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY, indexes.map((index) => ({ path: `lines.${index}.reference`, code: "unavailable" })));

/** Opaque keyset cursor of the lot pickers: base64url(`YYYY-MM-DD|lotKey`), ≤ 200 chars. */
export function encodeLotCursor(date: string, lotKey: LotKey): string {
  return Buffer.from(`${date}|${lotKey}`, "utf8").toString("base64url");
}

/** Invalid → 400 VALIDATION_ERROR `cursor invalid`, before any query. */
export function decodeLotCursor(value: string): { date: string; lotKey: LotKey } {
  const invalid = () => validationException([{ path: "cursor", code: "invalid" }]);
  if (!/^[A-Za-z0-9_-]{1,200}$/.test(value)) throw invalid();
  const match = /^(\d{4}-\d{2}-\d{2})\|(.{34,38})$/.exec(Buffer.from(value, "base64url").toString("utf8"));
  // INV-20261121-002 H3: a calendar date (Date.parse accepts 2026-02-31, PostgreSQL's ::date does not).
  if (!match || Number.isNaN(Date.parse(match[1])) || new Date(`${match[1]}T00:00:00Z`).toISOString().slice(0, 10) !== match[1] || !LOT_KEY_RE.test(match[2])) throw invalid();
  return { date: match[1], lotKey: match[2] };
}

/**
 * Line reference rule (api-contract "changed inputs", Q-LOT-09): a stock line names exactly one of an item id (legacy) or
 * a lot. A NEW line with an item id is refused with `lines.N.reference lot_required` once `newItemRefs` is false;
 * a line whose item is already on the stored document stays accepted (legacy lines are never converted).
 * Switched off with FE-LOT-008 (INV-20261121-002 H2): the frontend sends only `lotKey` for new picks. The only test seam is
 * `LOT_TEST_ACCEPT_ITEM_REFS=1` under Vitest, so the suites of the pre-lot item flows keep covering the legacy paths.
 */
export const ACCEPT_NEW_ITEM_REFERENCES = false;
export const acceptNewItemReferences = (): boolean =>
  ACCEPT_NEW_ITEM_REFERENCES || (process.env.VITEST === "true" && process.env.LOT_TEST_ACCEPT_ITEM_REFS === "1");

export function itemReferenceErrors(
  lines: readonly { memoStockId?: string | null; ownStockId?: string | null; lotKey?: string | null }[],
  stored: { memoStockIds: ReadonlySet<string>; ownStockIds: ReadonlySet<string> },
  newItemRefs = acceptNewItemReferences(),
) {
  const errors: { path: string; code: string }[] = [];
  lines.forEach((line, index) => {
    if (line.lotKey) {
      const source = line.memoStockId ? "STOCK" : line.ownStockId ? "OWN_STOCK" : null;
      if (source !== null || !isLotKey(line.lotKey)) errors.push({ path: `lines.${index}.reference`, code: "invalid" });
      return;
    }
    if (newItemRefs) return;
    if (line.memoStockId && !stored.memoStockIds.has(line.memoStockId)) errors.push({ path: `lines.${index}.reference`, code: "lot_required" });
    if (line.ownStockId && !stored.ownStockIds.has(line.ownStockId)) errors.push({ path: `lines.${index}.reference`, code: "lot_required" });
  });
  return errors;
}
